const vm=require('node:vm'),fs=require('node:fs'),assert=require('node:assert/strict');
const ctx={window:{},document:{documentElement:{lang:'uk'},addEventListener(){}},profileStorage:{getItem:()=>null}};vm.createContext(ctx);for(const path of ['assets/adaptive/benno-audio.js','assets/adaptive/benno-conversation.js'])vm.runInContext(fs.readFileSync(path,'utf8'),ctx);
const c=ctx.window.DEUTSCH_BENNO_CONVERSATION;
assert.equal(c.match('hello','  guten tag '),'Guten Tag!');assert.equal(c.match('hunger','Ja. ich habe Hunger!'),'Ja, ich habe Hunger.');assert.equal(c.match('thirst','ich habe durst'),'Ich habe Durst.');assert.equal(c.match('time','Ja, ich habe Hunger.'),null);assert.equal(c.match('hunger','Ja.'),null);assert.equal(c.match('bye','Hallo!'),null);
const orders=new Set();for(let n=0;n<100;n++){const p=c.plan();assert.equal(p.length,6);assert.equal(p[0],'hello');assert.equal(p[4],'thanks');assert.equal(p[5],'bye');assert.equal(new Set(p).size,6);const previous=p.slice(1,4);assert.notEqual(c.plan(previous).slice(1,4).join('|'),previous.join('|'));orders.add(previous.join('|'))}assert(orders.size>1);
assert.equal(c.availability().ready,3);assert.equal(c.availability().total,12);assert.equal(c.audioFor('benno','hello'),null);assert.equal(c.audioFor('benno','hunger'),null);assert(c.audioFor('you','hello').includes('oleksii-dylan'));assert.equal(c.audioFor('you','hunger'),null);assert.equal(c.audioFor('you','thanks','Danke, Benno!'),null);assert.equal(c.read(),null);
console.log('PASS Benno plans and exact replies: all six situations, shuffled questions, no repeated completed order, meaningful variants and role-specific whole recording availability');
